"""User-provided pirate-themed default sidebar artwork, resized to 72 px for TV and web."""
from base64 import b64decode

ICONS = {
    "home": "",
    "movies": "",
    "tv": "",
    "radarr": "",
    "sonarr": "",
    "sabnzbd": "",
    "settings": "",
}

def default_icon_png(name: str) -> bytes:
    return b64decode(ICONS[name])
